:{"calories_kcal":256,"protein_g":2.6,"fat_g":18.2,"carbohydrates_g":20.4,"per":"100 g"},"available":true,"stock_qty":null,"code":"1658620","source_url":"https://rostics.ru/product/80083"},{"name":"Ай-ролл по-русски","brand":"ROSTIC'S","nutrition":{"calories_kcal":281,"protein_g":11.1,"fat_g":11.8,"carbohydrates_g":32.5,"per":"100 g"},"available":true,"stock_qty":null,"code":"1658625","source_url":"https://rostics.ru/product/80314"},{"name":"Пунш Облепиха-Морошка","brand":"ROSTIC'S","nutrition":{"calories_kcal":30,"protein_g":0.1,"fat_g":0,"carbohydrates_g":7.3,"per":"100 ml"},"available":true,"stock_qty":null,"code":"1658892","source_url":"https://rostics.ru/product/88890"},{"name":"Игрушка Легенды космоса + Картофель фри малый","brand":"ROSTIC'S","nutrition":{"calories_kcal":291,"protein_g":3.6,"fat_g":20.7,"carbohydrates_g":22.6,"per":"100 g"},"available":true,"stock_qty":null,"code":"1668994","source_url":"https://rostics.ru/product/80569"},{"name":"Бабл Лимонад Облепиха-Морошка","brand":"ROSTIC'S","nutrition":{"calories_kcal":58,"protein_g":0.1,"fat_g":0,"carbohydrates_g":14.4,"per":"100 ml"},"available":true,"stock_qty":null,"code":"1670959","source_url":"https://rostics.ru/product/80437"},{"name":"Пирожок Малина-Крем-чиз","brand":"ROSTIC'S","nutrition":{"calories_kcal":291,"protein_g":3.4,"fat_g":16.1,"carbohydrates_g":33.2,"per":"100 g"},"available":true,"stock_qty":null,"code":"1670964","source_url":"https://rostics.ru/product/88892"}]}$fast_food_dataset$::jsonb)
),
source AS (
    SELECT
        btrim(replace(product->>'name', chr(160), ' ')) AS name,
        btrim(product->>'brand') AS brand,
        btrim(product->>'code') AS code,
        btrim(product->>'source_url') AS source_url,
        btrim(product->'nutrition'->>'per') AS nutrition_basis,
        (product->'nutrition'->>'calories_kcal')::double precision AS calories,
        (product->'nutrition'->>'protein_g')::double precision AS protein,
        (product->'nutrition'->>'fat_g')::double precision AS fat,
        (product->'nutrition'->>'carbohydrates_g')::double precision AS carbohydrate
    FROM dataset
    CROSS JOIN LATERAL jsonb_array_elements(payload->'products') AS item(product)
    WHERE COALESCE((product->>'available')::boolean, FALSE)
),
valid AS (
    SELECT *, CASE nutrition_basis WHEN '100 ml' THEN 'ml' ELSE 'g' END AS nutrition_unit
    FROM source
    WHERE name <> ''
      AND brand IN ('ВКУСНО — И ТОЧКА', 'БУРГЕР КИНГ', 'ROSTIC''S')
      AND code ~ '^[A-Za-z0-9_-]+$'
      AND source_url ~ '^https://'
      AND nutrition_basis IN ('100 g', '100 ml')
      AND calories BETWEEN 0 AND 1000
      AND protein BETWEEN 0 AND 100
      AND fat BETWEEN 0 AND 100
      AND carbohydrate BETWEEN 0 AND 100
)
INSERT INTO food_catalog (
    provider, external_id, barcode, name, brand_name, description,
    calories_per_100g, carbohydrate_per_100g, protein_per_100g, fat_per_100g,
    servings, data_quality
)
SELECT
    'community',
    'fast-food-moscow-' || md5(lower(brand) || ':' || code),
    '',
    name,
    brand,
    '',
    calories,
    carbohydrate,
    protein,
    fat,
    jsonb_build_array(jsonb_build_object(
        'id', nutrition_unit,
        'description', CASE nutrition_unit WHEN 'ml' THEN 'мл' ELSE 'г' END,
        'metricAmount', 1,
        'metricUnit', nutrition_unit,
        'numberOfUnits', 100,
        'measurement', CASE nutrition_unit WHEN 'ml' THEN 'мл' ELSE 'г' END,
        'calories', calories,
        'carbohydrate', carbohydrate,
        'protein', protein,
        'fat', fat
    )),
    0.95
FROM valid
ON CONFLICT (provider, external_id) DO UPDATE SET
    name = EXCLUDED.name,
    brand_name = EXCLUDED.brand_name,
    description = EXCLUDED.description,
    calories_per_100g = EXCLUDED.calories_per_100g,
    carbohydrate_per_100g = EXCLUDED.carbohydrate_per_100g,
    protein_per_100g = EXCLUDED.protein_per_100g,
    fat_per_100g = EXCLUDED.fat_per_100g,
    servings = EXCLUDED.servings,
    data_quality = EXCLUDED.data_quality,
    cached_at = now();
